    """Bounded decoder. Trailing bytes, unknown tags, non-NFC strings, unsorted or duplicate map keys
    and out-of-range counts all refuse; nothing is repaired."""
    value, offset = _cve1_read(raw, 0)
    if offset != len(raw):
        raise AdmissionError("CVE1_TRAILING_BYTES")
    return value


def _cve1_read(raw: bytes, offset: int):
    if offset >= len(raw):
        raise AdmissionError("CVE1_TRUNCATED")
    tag = raw[offset]; offset += 1
    if tag == 0x00:
        return None, offset
    if tag == 0x01:
        return False, offset
    if tag == 0x02:
        return True, offset
    if tag in (0x03, 0x07):
        if offset + 8 > len(raw):
            raise AdmissionError("CVE1_TRUNCATED")
        chunk = int.from_bytes(raw[offset:offset + 8], "big"); offset += 8
        if tag == 0x03:
