    if tag in (0x05, 0x06):
        if offset + 4 > len(raw):
            raise AdmissionError("CVE1_TRUNCATED")
        count = int.from_bytes(raw[offset:offset + 4], "big"); offset += 4
        if count > _CVE1_MAX_ITEMS:
