        if absent["coverageState"] not in registries["COVERAGE-STATE-DOMAIN-V1"]["members"]:
            refusals.append("capability.adm-domain:coverageState:" + str(absent["coverageState"]))
    if cve1_encode(value) != committed_bytes:
